   567
   568                  r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_CLASS, &obj_class);
   569                  if (r < 0) {
   570                          goto fail;
   571                  }
   572                  switch (obj_class) {
   573                  case CKO_PRIVATE_KEY:
   574                          r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_KEY_TYPE, &key_type);
   575                          /* default to CKK_RSA */
   576                          if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
   577                                  key_type = CKK_RSA;
   578                                  r = SC_SUCCESS;
   579                          }
   580                          if (r < 0) {
   581                                  goto fail;
   582                          }
   583                          /* set the info values */
   584                          obj_info = &prkey_info;
   585                          memset(&prkey_info, 0, sizeof(prkey_info));
   586                          coolkey_get_id(card, &coolkey_obj, &prkey_info.id);
   587                          prkey_info.path = coolkey_obj.path;
   588                          prkey_info.key_reference = coolkey_obj.id;
   589                          prkey_info.native = 1;
   590                          coolkey_get_usage(card, &coolkey_obj, &prkey_info.usage);
   591                          coolkey_get_access(card, &coolkey_obj, &prkey_info.access_flags);
   592                          key = coolkey_get_public_key(p15card, &coolkey_obj, key_type);
   593                          if (key_type == CKK_RSA) {
   594                                  obj_type = SC_PKCS15_TYPE_PRKEY_RSA;
   595                                  if (key) {
   596                                          prkey_info.modulus_length =  key->u.rsa.modulus.len*8;
   597                                  }
   598                          } else if (key_type == CKK_EC) {
   599                                  obj_type = SC_PKCS15_TYPE_PUBKEY_EC;
   600                                  if (key) {
   601                                          prkey_info.field_length =  key->u.ec.params.field_length;
   602                                  }
   603                          } else {
   604                                  goto fail;
   605                          }
   606                          break;
   607
   608                  case CKO_PUBLIC_KEY:
   609                          r = coolkey_get_attribute_ulong(card, &coolkey_obj, CKA_KEY_TYPE, &key_type);
   610                          /* default to CKK_RSA */
   611                          if (r == SC_ERROR_DATA_OBJECT_NOT_FOUND) {
   612                                  key_type = CKK_RSA;
   613                                  r = SC_SUCCESS;
   614                          }
   615                          if (r < 0) {
   616                                  goto fail;
   617                          }
   618                          key = coolkey_get_public_key(p15card, &coolkey_obj, key_type);
   619                          if (key == NULL) {
   620                                  goto fail;
   621                          }
   622                          /* set the info values */
   623                          obj_info = &pubkey_info;
   624                          memset(&pubkey_info, 0, sizeof(pubkey_info));
   625                          r = sc_pkcs15_encode_pubkey_as_spki(card->ctx, key, &pubkey_info.direct.spki.value,
   626                                                                                                                                                          &pubkey_info.direct.spki.len);
   627                          if (r < 0)
   628                                  goto fail;
   629                          coolkey_get_id(card, &coolkey_obj, &pubkey_info.id);
   630                          pubkey_info.path = coolkey_obj.path;
   631                          pubkey_info.native        = 1;
   632                          pubkey_info.key_reference = coolkey_obj.id;
   633                          coolkey_get_usage(card, &coolkey_obj, &pubkey_info.usage);
   634                          coolkey_get_access(card, &coolkey_obj, &pubkey_info.access_flags);
   635                          if (key_type == CKK_RSA) {
   636                                  obj_type = SC_PKCS15_TYPE_PUBKEY_RSA;
   637                                  pubkey_info.modulus_length =  key->u.rsa.modulus.len*8;
   638                          } else if (key_type == CKK_EC) {
   639                                  obj_type = SC_PKCS15_TYPE_PUBKEY_EC;
   640                                  pubkey_info.field_length =  key->u.ec.params.field_length;
   641                          } else {
   642                                  goto fail;
   643                          }
   644                          /* set the obj values */
   645                          obj_obj.emulated = key;
   646                          key = NULL;
   647                          break;
   648
   649                  case CKO_CERTIFICATE:
   650                          obj_info = &cert_info;
   651                          memset(&cert_info, 0, sizeof(cert_info));
   652                          coolkey_get_id(card, &coolkey_obj, &cert_info.id);
   653                          cert_info.path = coolkey_obj.path;
   654                          obj_type = SC_PKCS15_TYPE_CERT_X509;
   655
   656                          /* following will find the cached cert in cert_info */
   657                          r = coolkey_get_certificate(card, &coolkey_obj, &cert_info.value);
   658                          if (r < 0) {
   659                                  goto fail;
   660                          }
   661                          break;
   662
   663
   664                  default:
   665                          /* no other recognized types which are stored 'on card' */
   666                          break;
   667                  }
   668                  if (obj_info == NULL) {
   669                          continue;
   670                  }
   671
   672                  r = sc_pkcs15emu_object_add(p15card, obj_type, &obj_obj, obj_info);
   673                  if (r != SC_SUCCESS)
   674                          sc_log(card->ctx, "sc_pkcs15emu_object_add() returned %d", r);
   675  fail:
   676                  if (key) { sc_pkcs15_free_pubkey(key); }
   677
   678          }
   679          r = (card->ops->card_ctl)(card, SC_CARDCTL_COOLKEY_FINAL_GET_OBJECTS, &count);
